  x.beginPath(); ACG_LAND.forEach(r=>{r.forEach((p,i)=>{const q=acgXY(v,W,H,p[0],p[1]); if(i)x.lineTo(q[0],q[1]); else x.moveTo(q[0],q[1]);}); x.closePath();});
