  // 1 KP Graphs: the Moon string; every lower level allows or denies what the level above proposes
  const sg=SEGS[findSeg(P.Mo)], sl=SMA_SL[Math.floor(P.Mo/30)%12], L=[['sign lord',sl],['star lord',sg.star],['sub lord',sg.sub]];
