  const sig=(ch,p)=>uniq(hs(ch,starOf(ch,p)).concat(hs(ch,p)));
  const cuspSub=(ch,n)=>segOf(ch.cusp[n-1]).sub;
  /* class of a planet for trading: P profit, p weak profit, M mixed, A avoid, N neutral */
  function cls(ch,p){
    ch._c=ch._c||{}; if(ch._c[p])return ch._c[p];
    const st=hs(ch,starOf(ch,p)), s=sig(ch,p), f=inter(st,PRO).length, b=inter(st,AVD).length;
    let c; if(f&&!b)c='P'; else if(f&&b)c='M'; else if(!f&&b)c='A'; else{ const f2=inter(s,PRO).length, b2=inter(s,AVD).length; c=f2&&!b2?'p':f2&&b2?'M':b2?'A':'N'; }
    return ch._c[p]=c;
  }
  const CV={P:3,p:1.5,M:0.5,N:0,A:-3};
  const CLN={P:['Profit planet','லாப கிரகம்'],p:['Mild profit planet','மெல்லிய லாப கிரகம்'],M:['Mixed','கலவை'],N:['Neutral','சமம்'],A:['Avoid','தவிர்']};
  /* ---- Parashari (sign-based) helpers from the lagna ---- */
  const lagS=ch=>Math.floor(ch.cusp[0]/30)%12;
