    [1,2,3,5,6,8,9,10,11].forEach(n=>{ const sub=cuspSub(ch,n), st=starOf(ch,sub); S[n]={n:n,sub:sub,star:st,hT:hs(ch,st),sg:sig(ch,sub),seg:segOf(ch.cusp[n-1])}; });
    const s5=S[5], f5=inter(s5.sg,PRO), b5=inter(s5.sg,AVD), self5=s5.sg.indexOf(5)>=0, tf=inter(s5.hT,PRO), tb=inter(s5.hT,AVD);
    const deny5=f5.length===0&&(b5.length>0||self5);
    const fav=n=>{ const x=S[n]; return inter(x.sg,PRO).length>0&&inter(x.sg,AVD).length===0; };
    const bad=n=>inter(S[n].sg,AVD).length>0&&inter(S[n].sg,PRO).length===0;
