    add(fav(11)?1:bad(11)?-1:0,'11th cusp sub lord '+PN(S[11].sub)+' signifies '+S[11].sg.join(', ')+(fav(11)?': gains materialise':bad(11)?': gains slip away':': mixed'),'11-ஆம் பாவ உப அதிபதி '+TA[S[11].sub]+' குறிக்கும் பாவங்கள் '+S[11].sg.join(', '));
    add(fav(2)?1:bad(2)?-1:0,'2nd cusp sub lord '+PN(S[2].sub)+' signifies '+S[2].sg.join(', ')+(fav(2)?': money flows in':bad(2)?': money drains out':': mixed'),'2-ஆம் பாவ உப அதிபதி '+TA[S[2].sub]+' குறிக்கும் பாவங்கள் '+S[2].sg.join(', '));
    add((mer==='P'||mer==='p')?1:mer==='A'?-1:0,'Mercury (quick analysis): '+CLN[mer][0],'புதன் (விரைவான கணிப்பு): '+CLN[mer][1]);
    add((moo==='P'||moo==='p')?1:moo==='A'?-1:0,'Moon (intuition for timing): '+CLN[moo][0],'சந்திரன் (நேர உணர்வு): '+CLN[moo][1]);
