    const bulk=['Ju','Ve'].map(p=>({p:p,n:inter(sig(ch,p),[2,5,7,8,11]).length,b:sig(ch,p).indexOf(12)>=0}));
    bulk.forEach(x=>{ if(x.n>=2&&!x.b)add(1,PN(x.p)+' signifies '+inter(sig(ch,x.p),[2,5,7,8,11]).join(', ')+': can bring a bulk amount','குறிக்கும் '+inter(sig(ch,x.p),[2,5,7,8,11]).join(', ')+': பெரும் தொகை வாய்ப்பு'); });
