    const p={n:n,st:st,cc:cc,lat:+lat.toFixed(4),lon:+lon.toFixed(4),tz:tz}, a=mpList(); a.unshift(p); try{ localStorage.setItem('ga_myplaces',JSON.stringify(a)); }catch(e){}
