    let tzf; try{ tzf=tzFn(tzs); }catch(e){ msg.textContent='The birth time zone was not recognised.'; return; }
    const tzt=($('ntTzT').value.trim()||tzs); let tzt2; try{ tzt2=tzFn(tzt); }catch(e){ msg.textContent='The trading time zone was not recognised.'; return; }
