    const D=GA_FT.daysOf(f,t,'00:00','23:59',tzt); if(D.nd<1){ msg.textContent='The to date must not be before the from date.'; return; } if(D.nd>31){ msg.textContent='Please choose at most 31 days.'; return; }
    const d=dob.split('-').map(Number), tt=tob.split(':').map(Number), sec=tt[2]||0, lt=localToUtc(d[0],d[1],d[2],tt[0],tt[1],tzs), bms=lt.ms+sec*1000;
    msg.className='msg'; $('ntGo').disabled=true;
