    const good=R.per.filter(p=>p.g[2]==='yes').slice(0,12), cur=R.per.find(p=>p.s<=Date.now()&&p.e>Date.now()), bad=R.per.filter(p=>p.g[2]==='no').slice(0,6);
    h+=SEC('Lucky and unlucky periods of life (next 12 years)','வாழ்க்கையில் அதிர்ஷ்ட / சோதனை காலங்கள்');
