  const PN=p=>N.PN(p);
  const HM=[['Self, health, effort','தன்னம்பிக்கை, உடல்நலம், முயற்சி'],['Money, family, speech','செல்வம், குடும்பம், பேச்சு'],['Courage, communication, short travel, change of residence','தைரியம், தொடர்பு, குறுகிய பயணம், இடமாற்றம்'],['Home, education, vehicle, peace','வீடு, கல்வி, வாகனம், மன அமைதி'],['Children, speculation, intelligence','குழந்தை, ஊகம், புத்திக்கூர்மை'],['Service, debts, disease, competition','சேவை, கடன், நோய், போட்டி'],['Spouse, partnership, business','வாழ்க்கைத் துணை, கூட்டு, வியாபாரம்'],['Sudden events, obstacles, inheritance','திடீர் நிகழ்வு, தடை, பூர்வீகம்'],['Fortune, higher education, long journey','பாக்கியம், உயர்கல்வி, நீண்ட பயணம்'],['Career, status, profession','தொழில், பதவி, அந்தஸ்து'],['Gains, fulfilment of desires','லாபம், ஆசை நிறைவேறல்'],['Loss, foreign land, hospital, expenses','விரயம், வெளிநாடு, மருத்துவமனை, செலவு']];
  const hmShort=h=>HM[h-1][0].split(',')[0];
  /* ---- the chart helpers ---- */
  const hOf=(ch,l)=>{ for(let i=0;i<12;i++){ if(mod(l-ch.cusp[i])<mod(ch.cusp[(i+1)%12]-ch.cusp[i]))return i+1; } return 12; };
  const lordOf=(ch,h)=>N.segOf(ch.cusp[h-1]).lord;
