  const BYID={}; EV.forEach(e=>{BYID[e.id]=e;});
  /* ---- strength of each planet for an event (KP: star of occupant, occupant, star of owner, owner) ---- */
  function pScore(ch,p,F,D){
    const q=starOf(ch,p), qh=hOf(ch,ch.lon[q]), ph=hOf(ch,ch.lon[p]), dsp=N.segOf(ch.lon[p]).lord;
    const rk=h=>{ if(qh===h)return 4; if(ph===h)return 3; if(lordOf(ch,h)===q)return 2; if(lordOf(ch,h)===p||(isNode(p)&&lordOf(ch,h)===dsp))return 1; return 0; };
    let s=0; const hit=[], den=[];
    F.forEach(h=>{ const r=rk(h); if(r){ s+=r; hit.push(h); } });
    D.forEach(h=>{ if(rk(h)>=2)den.push(h); });
    let sv=Math.min(1,s/8);
    if(den.length)sv*=(hit.length>den.length?0.6:0.35);
    const rs=retro(ch,q); if(rs)sv*=0.6;
    const sg=N.sig(ch,subOf(ch,p)); if(hit.length&&!inter(sg,F).length)sv*=0.8;
    return {p:p,s:s,sv:sv,hit:hit,den:den,rs:rs,rp:retro(ch,p)};
  }
  function planetScores(ch,ev){ const o={}; CODES.forEach(p=>{ o[p]=pScore(ch,p,ev.F,ev.D); }); return o; }
  /* ---- is the matter promised? the sub lord of the cusp, read through its star lord ---- */
  function promise(ch,ev){
    const rs=ev.cs.map(c=>{
      const sb=N.cuspSub(ch,c), st=starOf(ch,sb), A=N.hs(ch,st), Bh=N.hs(ch,sb);
      const f=uniq(inter(A,ev.F).concat(inter(Bh,ev.F))), d=uniq(inter(A,ev.D).concat(inter(Bh,ev.D))), fa=inter(A,ev.F), da=inter(A,ev.D);
      const need=Math.min(2,ev.F.length); let g=0; if(fa.length>=need&&!d.length)g=3; else if(f.length&&!d.length)g=2; else if(f.length&&d.length<f.length)g=1;
      return {c:c,sb:sb,st:st,A:A,B:Bh,f:f,d:d,g:g,rs:retro(ch,st),rb:retro(ch,sb)};
    });
    const sc=rs.reduce((a,x)=>a+x.g,0)/rs.length;
    return {rs:rs,sc:sc,g:sc>=2.5?3:sc>=1.7?2:sc>=0.8?1:0};
  }
  const GRADE=[['Weak / delayed','பலவீனம் / தாமதம்','n'],['Mixed','கலவை','m'],['Promised','உறுதி','y'],['Strongly promised','வலுவான உறுதி','y']];
  /* ---- dasha, bhukti, antara ---- */
  function dasha3(ch,from,to){
    const mo=ch.lon.Mo, ns=360/27, i=Math.floor(mo/ns), fr=(mo-i*ns)/ns, d0=ORD[i%9], k=ORD.indexOf(d0), out=[];
    let t=ch.ms-fr*YR[d0]*YMS;
    for(let g=0;g<27&&t<to;g++){
      const md=ORD[(k+g)%9], mdl=YR[md]*YMS, me=t+mdl;
      if(me>from){ let bt=t; for(let b=0;b<9;b++){ const ad=ORD[(ORD.indexOf(md)+b)%9], bl=mdl*YR[ad]/120, be=bt+bl;
        if(be>from&&bt<to){ let pt=bt; for(let c=0;c<9;c++){ const pd=ORD[(ORD.indexOf(ad)+c)%9], pl=bl*YR[pd]/120, pe=pt+pl; if(pe>from&&pt<to)out.push({md:md,ad:ad,pd:pd,s:pt,e:pe}); pt=pe; } }
        bt=be; } }
      t=me;
    }
    return out;
  }
  const adWins=list=>{ const o=[]; list.forEach(x=>{ const L=o[o.length-1]; if(L&&L.md===x.md&&L.ad===x.ad){ L.e=x.e; L.pds.push(x); } else o.push({md:x.md,ad:x.ad,s:x.s,e:x.e,pds:[x]}); }); return o; };
  /* ---- daily transit tables (Sun, Jupiter, Saturn) for the timing windows ---- */
  function transitTable(ch,t0,days){
    const old=CFG; CFG={lat:0,lon:0,kind:ch.kind}; const T={t0:t0,n:days,Su:[],Ju:[],Sa:[]};
    try{ for(let i=0;i<days;i++){ const ms=t0+i*DAY+12*3600000; ['Su','Ju','Sa'].forEach(b=>{ const l=sidLon(b,ms), g=SEGS[findSeg(l)]; T[b].push([g.star,g.lord,g.sub,l]); }); } }
    finally{ CFG=old; }
    return T;
  }
  const winsOf=(n,fn)=>{ const o=[]; let a=-1; for(let i=0;i<=n;i++){ const ok=i<n&&fn(i); if(ok&&a<0)a=i; else if(!ok&&a>=0){ o.push([a,i-1]); a=-1; } } return o; };
  /* ---- timing of one event ---- */
  function timing(ch,ev,PS,per,TT,from,to){
    const ads=adWins(per), out=[];
    ads.forEach(w=>{
      const m=PS[w.md].sv, a=PS[w.ad].sv; if(m<0.12||a<0.12)return;
      let best=0; const pds=w.pds.map(x=>({pd:x.pd,s:x.s,e:x.e,v:PS[x.pd].sv})).filter(x=>x.v>=0.3&&x.e>from&&x.s<to);
      pds.forEach(x=>{ if(x.v>best)best=x.v; });
      const sc=0.3*m+0.5*a+0.2*best, st=Math.max(w.s,from), en=Math.min(w.e,to);
      if(sc<0.2||en<=st)return;
      out.push({md:w.md,ad:w.ad,s:w.s,e:w.e,sc:sc,pds:pds.sort((x,y)=>y.v-x.v).slice(0,3).sort((x,y)=>x.s-y.s),tr:null});
    });
    // transit confirmation: Jupiter for the year, the Sun for the month (both in the sign or star of a significator)
    const SG=CODES.filter(p=>PS[p].sv>=0.3);
    if(TT&&SG.length){
      const okf=(b,i)=>{ const r=TT[b][i]; return SG.indexOf(r[0])>=0||SG.indexOf(r[1])>=0; };
      out.forEach(o=>{
        if(o.sc<0.35||o.e<=Date.now())return;
        const a=Math.max(0,Math.floor((Math.max(o.s,Date.now())-TT.t0)/DAY)), b=Math.min(TT.n-1,Math.floor((Math.min(o.e,to)-TT.t0)/DAY));
        if(b<a)return;
        const both=winsOf(b+1,i=>i>=a&&okf('Su',i)&&okf('Ju',i)), sun=winsOf(b+1,i=>i>=a&&okf('Su',i));
        o.tr={both:both.slice(0,4).map(x=>[TT.t0+x[0]*DAY,TT.t0+(x[1]+1)*DAY]),sun:sun.length,juOk:both.length>0};
        if(!both.length)o.tr.sunw=sun.slice(0,3).map(x=>[TT.t0+x[0]*DAY,TT.t0+(x[1]+1)*DAY]);
      });
    }
    return out;
  }
  const LV=sc=>sc>=0.62?['Very likely','மிக வாய்ப்பு','y']:sc>=0.4?['Likely','வாய்ப்பு','y']:['Possible','சாத்தியம்','m'];
  /* ---- the report ---- */
  function build(o){
    const kind=o.kind, fd=o.fd, now=Date.now(), ch=N.chart(o.ms,o.lat,o.lon,kind);
    const from=now-2*365.25*DAY, to=now+12*365.25*DAY;
    const per=dasha3(ch,from,to), t0=Math.floor(from/DAY)*DAY, TT=transitTable(ch,t0,Math.ceil((to-t0)/DAY));
    const R={}, PSm={};
    EV.forEach(ev=>{ const PS=planetScores(ch,ev), pr=promise(ch,ev), tm=timing(ch,ev,PS,per,TT,from,to);
      const kb=ev.k.length?Math.max.apply(null,ev.k.map(p=>PS[p].sv)):0; pr.kb=kb; if(ev.k.length){ if(kb>=0.3&&pr.sc>0.5)pr.sc=Math.min(3,pr.sc+0.25); else if(kb<0.1&&pr.sc>=1.7)pr.sc-=0.2; pr.g=pr.sc>=2.5?3:pr.sc>=1.7?2:pr.sc>=0.8?1:0; }
      R[ev.id]={ev:ev,PS:PS,pr:pr,tm:tm}; PSm[ev.id]=PS; });
    const ctx={ch:ch,R:R,per:per,TT:TT,fd:fd,from:from,to:to,now:now,o:o};
    let html='', text=[];
    const secs=[summary(ctx),suggest(ctx),running(ctx)]; for(let n=1;n<=12;n++)secs.push(houseSection(ctx,n)); secs.push(timeline(ctx),transitNow(ctx),finder(ctx),notes());
    html='<div id="bpPredBox"><div class="lf-sec"><h3>Predictions from the birth chart, dasha and transit<span class="ta">ஜாதகம், தசா, கோசாரப் பலன்கள்</span></h3></div>'+secs.join('')+'</div>';
    return {html:html,ctx:ctx};
  }
  /* ---- pieces ---- */
  const chip=g=>'<span class="pill '+(g[2]==='y'?'gain':'')+'">'+g[0]+' · '+g[1]+'</span>';
  const row=(cls,inner)=>'<div class="ntr '+cls+'">'+inner+'</div>';
  const fmtP=(ctx,x)=>ctx.fd(Math.max(x.s,ctx.from))+' → '+ctx.fd(x.e);
