    const ch=ctx.ch, c=ctx.per.find(x=>x.s<=ctx.now&&x.e>ctx.now); let h='<div class="lf-sec"><h3>'+B('Running period','நடப்பு தசா-புக்தி-அந்தரம்')+'</h3></div>';
