    h+=row('y','<b>'+B('Fields of work that suit you','பொருந்தும் துறைகள்')+'</b>'+top.map(p=>'<br>'+B(PN(p)+': '+PROF[p][0],TA[p]+': '+PROF[p][1])).join(''));
    const r10=[]; if(ci(s10,[1,5,9,12])&&!ci(s10,[2,6,10,11]))r10.push(B('The 10th sub lord gives 1, 5, 9 or 12 without 2, 6, 10, 11: dismissal or loss of status is possible; guard the job','10-ஆம் உப அதிபதி 1, 5, 9, 12 மட்டும்: வேலை இழப்பு / பதவி இழப்பு வாய்ப்பு'));
    if(ci(N.sig(ch,c10),[7,8,12])&&ci(N.sig(ch,c10),[7])&&ci(N.sig(ch,c10),[8,12]))r10.push(B('The 10th sub lord touches 7, 8 and 12: avoid tax and legal troubles','10-ஆம் உப அதிபதி 7, 8, 12: வரி, சட்டச் சிக்கல்களைத் தவிர்க்கவும்'));
    if(c10==='Sa'&&ci(s10,[11]))r10.push(B('Saturn as the 10th sub lord with 11: stay honest in money matters','சனி 10-ஆம் உப அதிபதியாக 11-ஐத் தருவதால் பணத்தில் நேர்மை அவசியம்'));
    r10.forEach(x=>{ h+=row('n',x); });
    h+='</div>';
    return h;
