  let studied=false;
  function init(){
    const anchor=$('munBox')||document.querySelector('#eqPanel .acres.warn'); if(!anchor)return;
    const iso=new Date(Date.now()+TZ*3600000).toISOString().slice(0,10), iso2=new Date(Date.now()+TZ*3600000+183*DAY).toISOString().slice(0,10);
    const html='<div id="aviBox"><h3 class="eph3">Aircraft accidents: planetary study and forecast · விமான விபத்துகள்: கிரக ஆய்வு, முன்னறிவிப்பு</h3>'+
      '<details class="howto" id="avStudy"><summary>Study of 20 major crashes: planets, latitude and longitude<span class="tt">20 பெரிய விபத்துகள்: கிரகங்கள், அட்சரேகை, தீர்க்கரேகை</span></summary><div id="avStudyOut"><p class="lf-note">Opening…</p></div></details>'+
      '<div class="group"><label class="cell" for="avFrom"><span class="cl">From</span><input type="date" id="avFrom" value="'+iso+'"></label><label class="cell" for="avTo"><span class="cl">To</span><input type="date" id="avTo" value="'+iso2+'"></label><label class="cell" for="avMin"><span class="cl">Show</span><select id="avMin"><option value="1">Watch and above</option><option value="1.5" selected>Elevated and above</option><option value="2">High only</option></select></label><label class="cell" for="avReg"><span class="cl">Area</span><select id="avReg">'+Object.keys(REG).map(k=>'<option value="'+k+'">'+REG[k][0]+' · '+REG[k][1]+'</option>').join('')+'<option value="custom">Custom box · தனிப்பட்ட பகுதி</option></select></label></div>'+
      '<div class="group" id="avCust" style="display:none"><label class="cell"><span class="cl">South</span><input id="avLa0" inputmode="decimal" value="0"></label><label class="cell"><span class="cl">North</span><input id="avLa1" inputmode="decimal" value="40"></label><label class="cell"><span class="cl">West</span><input id="avLo0" inputmode="decimal" value="60"></label><label class="cell"><span class="cl">East</span><input id="avLo1" inputmode="decimal" value="100"></label></div>'+
      '<div class="btns"><button class="primary" id="avGo" type="button">Find air-hostile days and places · விமானத்துக்குக் கடின நாட்கள், இடங்கள்</button></div><div class="msg" id="avMsg" role="status"></div><div id="avOut" aria-live="polite"></div></div>';
    anchor.insertAdjacentHTML('afterend',html);
    $('avGo').addEventListener('click',run); $('avReg').addEventListener('change',()=>{ $('avCust').style.display=$('avReg').value==='custom'?'':'none'; });
    $('avStudy').addEventListener('toggle',()=>{ if($('avStudy').open&&!studied){ studied=true; setTimeout(()=>{ try{ const s=studyHtml($('ayan').value); $('avStudyOut').innerHTML=s.html; mapInit('avMap1'); setLayer('avMap1',EV.map((e,i)=>dot(e[4],e[5],'#d33',String(i+1),e[0]+' · '+e[1]+' · '+e[2],3.4)).join('')); }catch(e){ $('avStudyOut').innerHTML='<p class="lf-note">Could not build the study: '+e.message+'</p>'; if(window.console)console.error(e); } },20); } });
  }
  init();
