    h+='<p><b>'+ES(gm(T[2],T[3]))+' – '+L('from your birth chart, dasha and transit','உங்கள் ஜாதகம், தசா, கோசாரத்திலிருந்து')+'</b></p>';
    ids.forEach(id=>{ const r=ctx.R[id], ev=r.ev, g=r.pr.g;
      h+='<div class="ak-card"><b>'+ES(gm(ev.en,ev.ta))+'</b> <span class="ak-pill g'+g+'">'+ES(gm(GR[g][0],GR[g][1]))+'</span><ul>';
      r.pr.rs.forEach(x=>{ h+='<li>'+L('Cusp '+x.c+': sub lord '+NM(x.sb)+' (star lord '+NM(x.st)+') signifies houses '+(x.A.join(', ')||'–')+'; supporting '+(x.f.join(', ')||'none')+(x.d.length?'; denying '+x.d.join(', '):'')+(x.rs?'; star lord is retrograde (delay)':'')+'.','பாவ முனை '+x.c+': உப அதிபதி '+TM(x.sb)+' (நட்சத்திர அதிபதி '+TM(x.st)+') குறிக்கும் பாவங்கள் '+(x.A.join(', ')||'–')+'; ஆதரிப்பவை '+(x.f.join(', ')||'இல்லை')+(x.d.length?'; மறுப்பவை '+x.d.join(', '):'')+(x.rs?'; நட்சத்திர அதிபதி வக்கிரம் (தாமதம்)':'')+'.')+'</li>'; });
      const up=r.tm.filter(x=>x.e>now&&x.sc>=0.35).sort((a,b)=>a.s-b.s).slice(0,3);
      if(g===0&&ev.r!==undefined&&false){}
      h+='</ul>';
      if(up.length)h+='<div>'+L('Favourable periods ahead (dasha–bhukti–antara with transit): ','முன்னால் உள்ள சாதகக் காலங்கள் (தசா–புக்தி–அந்தரம், கோசாரத்துடன்): ')+'<b>'+up.map(x=>ctx.fd(Math.max(x.s,now))+' → '+ctx.fd(x.e)).join('; ')+'</b></div>';
      else h+='<div>'+L('No strong favourable period is seen in the next 12 years for this matter.','அடுத்த 12 ஆண்டுகளில் இந்த விஷயத்துக்கு வலுவான சாதகக் காலம் தெரியவில்லை.')+'</div>';
      h+='</div>'; });
    const c=ctx.per.find(x=>x.s<=now&&x.e>now);
    if(c)h+='<p>'+L('Running period: dasha '+NM(c.md)+', bhukti '+NM(c.ad)+', antara '+NM(c.pd)+' (antara until '+ctx.fd(c.e)+').','நடப்பு காலம்: தசை '+TM(c.md)+', புக்தி '+TM(c.ad)+', அந்தரம் '+TM(c.pd)+' (அந்தரம் '+ctx.fd(c.e)+' வரை).')+'</p>';
    try{ const old=CFG; CFG={lat:0,lon:0,kind:kindAyan()}; let ju,sa; try{ ju=sidLon('Ju',now); sa=sidLon('Sa',now); }finally{ CFG=old; }
      const asc=(typeof ctx.ch.cusp[0]==='number')?ctx.ch.cusp[0]:(ctx.ch.cusp[0]&&ctx.ch.cusp[0].lon)||0, hs=l=>((Math.floor(l/30)-Math.floor(asc/30)+12)%12)+1;
      h+='<p>'+L('Transit today: Jupiter in '+SGN[Math.floor(ju/30)%12][0]+' (your '+ord(hs(ju))+' house from the lagna), Saturn in '+SGN[Math.floor(sa/30)%12][0]+' (your '+ord(hs(sa))+' house).','இன்றைய கோசாரம்: குரு '+SGN[Math.floor(ju/30)%12][1]+' (லக்னத்திலிருந்து '+hs(ju)+'ஆம் வீடு), சனி '+SGN[Math.floor(sa/30)%12][1]+' ('+hs(sa)+'ஆம் வீடு).')+'</p>'; }catch(e){}
